(window.WSR_PARTS = window.WSR_PARTS || {})["erlkoenig"] = {"title": "Erlkönig", "lang": "de", "html": "<section>\n<div class=\"wsr-verse\"><div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"1\"><span class=\"wsr-page\" data-num=\"104\"></span><b>Erlkönig.</b></span></div>\n<div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"2\">Wer reitet so spät durch Nacht und Wind?</span>\n<span class=\"wsr-line\" data-n=\"3\">Es ist der Vater mit seinem Kind;</span>\n<span class=\"wsr-line\" data-n=\"4\">Er hat den Knaben wohl in dem Arm,</span>\n<span class=\"wsr-line\" data-n=\"5\">Er faßt ihn sicher, er hält ihn warm.</span></div>\n<div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"5\"><span class=\"wsr-ln-src\">5</span>Mein Sohn, was birgst du so bang dein Gesicht? —</span>\n<span class=\"wsr-line\" data-n=\"6\">Siehst, Vater, du den Erlkönig nicht?</span>\n<span class=\"wsr-line\" data-n=\"7\">Den Erlenkönig mit Kron’ und Schweif? —</span>\n<span class=\"wsr-line\" data-n=\"8\">Mein Sohn, es ist ein Nebelstreif. —</span></div>\n<div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"9\">„Du liebes Kind, komm, geh mit mir!</span>\n<span class=\"wsr-line\" data-n=\"10\"><span class=\"wsr-ln-src\">10</span>Gar schöne Spiele spiel’ ich mit dir;</span>\n<span class=\"wsr-line\" data-n=\"11\">Manch’ bunte Blumen sind an dem Strand,</span>\n<span class=\"wsr-line\" data-n=\"12\">Meine Mutter hat manch gülden Gewand.“ —</span></div>\n<div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"13\">Mein Vater, mein Vater, und hörest du nicht,</span>\n<span class=\"wsr-line\" data-n=\"14\">Was Erlenkönig mir leise verspricht? —</span>\n<span class=\"wsr-line\" data-n=\"15\"><span class=\"wsr-ln-src\">15</span>Sei ruhig, bleibe ruhig, mein Kind;</span>\n<span class=\"wsr-line\" data-n=\"16\">In dürren Blättern säuselt der Wind. —</span></div>\n<div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"17\">„Willst, feiner Knabe, du mit mir gehn?</span>\n<span class=\"wsr-line\" data-n=\"18\">Meine Töchter sollen dich warten schön;</span>\n<span class=\"wsr-line\" data-n=\"19\">Meine Töchter führen den nächtlichen Reihn</span>\n<span class=\"wsr-line\" data-n=\"20\"><span class=\"wsr-ln-src\">20</span>Und wiegen und tanzen und singen dich ein.“ —</span></div>\n<div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"21\">Mein Vater, mein Vater, und siehst du nicht dort</span>\n<span class=\"wsr-line\" data-n=\"22\">Erlkönigs Töchter am düstern Ort? —</span>\n<span class=\"wsr-line\" data-n=\"23\">Mein Sohn, mein Sohn, ich seh’ es genau:</span>\n<span class=\"wsr-line\" data-n=\"24\">Es scheinen die alten Weiden so grau. —</span></div>\n<div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"25\"><span class=\"wsr-ln-src\">25</span>„Ich liebe dich, mich reizt deine schöne Gestalt;</span>\n<span class=\"wsr-line\" data-n=\"26\">Und bist du nicht willig, so brauch’ ich Gewalt.“ —</span>\n<span class=\"wsr-line\" data-n=\"27\">Mein Vater, mein Vater, jetzt faßt er mich an!</span>\n<span class=\"wsr-line\" data-n=\"28\">Erlkönig hat mir ein Leids getan! —</span></div>\n<div class=\"wsr-stanza\"><span class=\"wsr-line\" data-n=\"29\">Dem Vater grauset’s; er reitet geschwind,</span>\n<span class=\"wsr-line\" data-n=\"30\"><span class=\"wsr-ln-src\">30</span>Er hält in Armen das ächzende Kind,</span>\n<span class=\"wsr-line\" data-n=\"31\">Erreicht den Hof mit Mühe und Not;</span>\n<span class=\"wsr-line\" data-n=\"32\">In seinen Armen das Kind war tot.</span></div></div>\n</section>"};
